<script lang="ts">
 import {zh} from './zh';
 import {untrack} from 'svelte';import AriaPopover from './AriaPopover.svelte';import AriaSymbol from './AriaSymbol.svelte';import {engine,type ScorePanels,type ScoreStyle} from '../../bridge/engine.svelte';import {workspace} from '../../library/workspace.svelte';import {saveAs} from '../../native';import AriaPractice from './AriaPractice.svelte';import AriaInstruments from './AriaInstruments.svelte';import AriaPartLayout from './AriaPartLayout.svelte';import AriaMixer from './AriaMixer.svelte';import AriaScoreForms from './AriaScoreForms.svelte';import type {AriaTool} from './tools';
 let {kind,phone,title,deckHeight=292,onclose,onerror,onaction,onedit}:{kind:string;phone:boolean;title:string;deckHeight?:number;onclose:()=>void;onerror:(message:string)=>void;onaction:(tool:AriaTool)=>void;onedit:(values:Record<string,unknown>)=>Promise<boolean>}=$props();
 let data=$state<ScorePanels>({parts:[],channels:[]}),style=$state<ScoreStyle|null>(null),size=$state('A4'),format=$state('mscz'),fileName=$state(untrack(()=>title)),working=$state(false);
 let margin=$state(15),staffSize=$state(1.75),staffSpacing=$state(6.5),systemSpacing=$state(8),pageWidth=210,pageHeight=297;
 let palette=$state<{name:string;index:number;cells:{name:string;png:string}[]}[]>([]);
 $effect(()=>{const k=kind;untrack(()=>{
  if(['mixer','parts','instruments'].includes(k))data=engine.scorePanels();
  if(k==='page'){style=engine.scoreStyle();pageWidth=style.width;pageHeight=style.height;size=Math.abs(pageWidth-210)<.75&&Math.abs(pageHeight-297)<.75?'A4':Math.abs(pageWidth-215.9)<.75&&Math.abs(pageHeight-279.4)<.75?'Letter':Math.abs(pageWidth-215.9)<.75&&Math.abs(pageHeight-355.6)<.75?'Legal':'Current';margin=style.left;staffSize=style.spatium;staffSpacing=style.staffDistance;systemSpacing=style.minSystemDistance;}
  if(k==='clef'){working=true;setTimeout(()=>{try{const group=k==='clef'?'Clefs':k==='key'?'Key signatures':'Time signatures';palette=engine.palettes().map((p,index)=>({...p,index})).filter(p=>p.name===group).map(p=>({name:p.name,index:p.index,cells:engine.palette(p.index)?.cells||[]}));}finally{working=false;}},16);}
 });});
 const sheetTitle=$derived(({setup:'Score Setup',autoBreaks:'Auto Breaks',tempo:'Tempo',transpose:'Transpose Score',transposeSelection:'Transpose',pickup:'Pickup Measure',addMeasures:'Add Multiple Measures...',practice:'Playback & Practice',mixer:'Mixer',parts:'Parts',instruments:'Instrument Layout',page:'Page Settings',export:'Export Score',clef:'Change Clef',key:'Key Signature',time:'Time Signature'} as Record<string,string>)[kind]||kind);
 async function pageApply(){if(!style)return;working=true;try{const dimensions=size==='Letter'?[215.9,279.4]:size==='Legal'?[215.9,355.6]:size==='Current'?[pageWidth,pageHeight]:[210,297];const reply=engine.applyScoreStyle({...style,width:dimensions[0],height:dimensions[1],left:margin,right:margin,top:margin,bottom:margin,spatium:staffSize,staffDistance:staffSpacing,minSystemDistance:systemSpacing});if(!reply.ok)throw Error(reply.message||'Page settings could not be applied.');await workspace.persist(true);onclose();}catch(e){onerror((e as Error).message);}finally{working=false;}}
 function mix(id:number,key:string,value:number|boolean){const r=engine.changeMixer({id,[key]:value});if(!r.ok)onerror('Mix could not be changed.');data=engine.scorePanels();}
 async function exportFile(){working=true;try{const mime=format==='pdf'?'application/pdf':format==='mid'?'audio/midi':'application/octet-stream',bytes=await engine.exportTo(format);await saveAs((fileName||title)+'.'+format,bytes,mime);onclose();}catch(e){onerror((e as Error).message);}finally{working=false;}}
 async function togglePart(id:string,visible:boolean){const r=engine.changeParts({op:'part-visible',id,visible});if(!r.ok)onerror('Part visibility could not be changed.');data=engine.scorePanels();}
 const percent=(db:number)=>Math.round(Math.pow(10,db/20)*100);
 const step=(which:'margin'|'staffSize'|'staffSpacing'|'systemSpacing',delta:number)=>{if(which==='margin')margin=Math.min(35,Math.max(5,margin+delta));if(which==='staffSize')staffSize=Math.min(2.4,Math.max(1.2,staffSize+delta));if(which==='staffSpacing')staffSpacing=Math.min(16,Math.max(3,staffSpacing+delta));if(which==='systemSpacing')systemSpacing=Math.min(24,Math.max(4,systemSpacing+delta));};
</script>
{#if kind==='instrumentPicker'}<AriaInstruments {phone} {onclose} {onedit}/>
{:else if kind==='mixer'&&!phone}
 <div class="tablet-mixer" role="dialog" aria-modal="false" aria-label="混音器" tabindex="-1" style:bottom={deckHeight+8+'px'} style:height={Math.min(Math.max((innerHeight-deckHeight)*.4,390),410)+'px'}><div class="mixer-handle"></div><AriaMixer {phone} {title} {onclose} {onerror}/></div>
{:else}
<AriaPopover title={zh(sheetTitle)} {onclose} width={kind==='mixer'?900:kind==='instruments'?736:560} height={kind==='mixer'?(phone?360:480):kind==='addMeasures'?260:kind==='autoBreaks'?380:kind==='tempo'?640:undefined}>
 {#if ['setup','autoBreaks','addMeasures','tempo','transpose','transposeSelection','pickup','key','time'].includes(kind)}
  <AriaScoreForms kind={kind==='transposeSelection'?'transpose':kind} whole={kind!=='transposeSelection'} {phone} {onclose} {onedit}/>
 {:else if kind==='page'}
  <div class="aria-form-header"><button onclick={onclose}>取消</button><strong>页面设置</strong><button disabled={working} onclick={pageApply}>应用</button></div>
  <div class="aria-form-body"><fieldset><legend>页面</legend><div class="form-section"><label class="form-row">纸张尺寸<select bind:value={size}>{#each ['A4','Letter','Legal',...(size==='Current'?['Current']:[])] as s}<option value={s}>{zh(s)}</option>{/each}</select></label><div class="form-row"><span>页边距 {margin.toFixed(0)} 毫米</span><div class="stepper"><button aria-label="减小页边距" onclick={()=>step('margin',-1)}>−</button><button aria-label="增大页边距" onclick={()=>step('margin',1)}>＋</button></div></div></div></fieldset>
   <fieldset><legend>记谱</legend><div class="form-section">{#each [{id:'staffSize' as const,label:'Staff size',value:staffSize,unit:' mm',decimals:2,delta:.05},{id:'staffSpacing' as const,label:'Staff spacing',value:staffSpacing,unit:'',decimals:1,delta:.5},{id:'systemSpacing' as const,label:'System spacing',value:systemSpacing,unit:'',decimals:1,delta:.5}] as field}<div class="form-row"><span>{zh(field.label)} {field.value.toFixed(field.decimals)}{field.unit}</span><div class="stepper"><button aria-label={zh('Decrease '+field.label)} onclick={()=>step(field.id,-field.delta)}>−</button><button aria-label={zh('Increase '+field.label)} onclick={()=>step(field.id,field.delta)}>＋</button></div></div>{/each}</div></fieldset><button class="reset" onclick={()=>{size='A4';margin=15;staffSize=1.75;staffSpacing=6.5;systemSpacing=8;}}>恢复默认</button></div>
 {:else if kind==='practice'}
  <AriaPractice/>
 {:else if kind==='mixer'}
  <AriaMixer {phone} {title} {onclose} {onerror}/>
 {:else if kind==='export'}
  <div class="export-panel"><h2>导出乐谱</h2>{#if !phone}<p>选择导出内容与格式</p>{/if}<strong class="sharing">导出：{title}</strong><label>文件名<input bind:value={fileName}/></label><label>格式<select bind:value={format}>{#each [['mscz','MuseScore'],['pdf','PDF'],['musicxml','MusicXML'],['mid','MIDI'],['png','PNG'],['svg','SVG']] as [ext,name]}<option value={ext}>{zh(name)}</option>{/each}</select></label><div class="export-footer"><button onclick={onclose}>取消</button><button class="primary" disabled={working} onclick={exportFile}>{zh(working?'Preparing…':'Export')}</button></div></div>
 {:else if kind==='instruments'}
  <AriaPartLayout {onclose} {onerror}/>
 {:else if kind==='parts'}
  <div class="aria-form-header"><strong>分谱</strong><button onclick={onclose}>完成</button></div><div class="part-choices">{#each engine.composerState({editorInfo:true})?.editorInfo?.parts||[] as part}<button onclick={async()=>{if(await onedit({op:'selectPart',id:part.id}))onclose();}}>{part.id==='full-score'?'总谱':part.name}{#if part.selected}<AriaSymbol name="checkmark" size={17}/>{/if}</button>{/each}</div>
 {:else if kind==='clef'}
  <div class="aria-form-header"><button onclick={onclose}>取消</button><strong>{zh(sheetTitle)}</strong></div><div class="clef-choices">{#each ['Treble','Alto','Tenor','Bass'] as name}<button disabled={working} onclick={()=>{for(const group of palette){const index=group.cells.findIndex(cell=>cell.name.toLowerCase()===name.toLowerCase()+' clef');if(index>=0&&engine.applyPaletteCell(group.index,index)){onclose();return;}}onerror('Select a note or measure first.');}}>{zh(name+' Clef')}</button>{/each}</div>
 {/if}
</AriaPopover>
{/if}
<style>
 .tablet-mixer{position:fixed;left:8px;right:8px;z-index:80;background:var(--aria-sunken);color:var(--aria-ink);border-radius:26px;box-shadow:0 -2px 20px #0002;overflow:hidden;display:flex;flex-direction:column;pointer-events:auto;}.tablet-mixer :global(.aria-mixer){min-height:0;flex:1;}.mixer-handle{flex:none;width:42px;height:5px;border-radius:3px;background:var(--aria-line);margin:8px auto 2px;}
 .stepper{display:flex;border-radius:8px;background:var(--aria-fill);}.stepper button{min-width:44px;height:32px;border:0;background:none;color:var(--aria-active);font-size:21px;}.stepper button+button{border-left:1px solid var(--aria-line);}.reset{border:0;background:none;color:var(--aria-active);font-size:16px;min-height:44px;}.export-panel{padding:22px;}.export-panel h2{font-size:20px;}.export-panel p{margin-top:4px;color:var(--aria-muted);}.sharing{display:block;margin:12px 0;color:var(--aria-active);font-size:13px;}.export-panel label{display:flex;flex-direction:column;gap:8px;margin:18px 0;}.export-panel input,.export-panel select{min-height:44px;padding:8px 12px;font-size:16px;border:1px solid var(--aria-line);border-radius:10px;background:var(--aria-surface);}.export-footer{display:flex;justify-content:end;gap:12px;}.export-footer button{min-height:44px;padding:0 20px;border:0;background:var(--aria-fill);border-radius:10px;}.export-footer .primary{background:var(--aria-active);color:var(--aria-on-active);}.clef-choices,.part-choices{display:flex;flex-direction:column;padding:8px 0;}.clef-choices button,.part-choices button{display:flex;justify-content:space-between;align-items:center;width:100%;min-height:48px;background:none;border:0;border-radius:0;padding:0 24px;text-align:left;font-size:16px;color:var(--aria-active);}
</style>
